# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DÖRT MEVSİM VE HAVA OLAYLARI (الْفُصُولُ الْأَرْبَعَةُ وَحَالَةُ الطَّقْسِ)</text>\n  <rect x="20" y="48" width="155" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="97" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">1. الرَّبِيعُ (İlkbahar)</text>\n  <text x="32" y="102" font-size="11" fill="#334155">• الْجَوُّ مُعْتَدِلٌ (Ilıman)</text>\n  <text x="32" y="128" font-size="11" fill="#334155">• الْأَزْهَارُ مُتَفَتِّحَةٌ</text>\n  <text x="32" y="154" font-size="11" fill="#334155">• السَّمَاءُ صَافِيَةٌ</text>\n  <text x="97" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">فَصْلُ الرَّبِيعِ جَمِيلٌ</text>\n  <rect x="188" y="48" width="155" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="265" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">2. الصَّيْفُ (Yaz)</text>\n  <text x="200" y="102" font-size="11" fill="#334155">• الْجَوُّ حَارٌّ (Sıcak)</text>\n  <text x="200" y="128" font-size="11" fill="#334155">• الْجَوُّ مُشْمِسٌ (Güneşli)</text>\n  <text x="200" y="154" font-size="11" fill="#334155">• الشَّمْسُ سَاطِعَةٌ</text>\n  <text x="265" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">الصَّيْفُ حَارٌّ وَمُشْمِسٌ</text>\n  <rect x="356" y="48" width="155" height="190" rx="8" fill="#fff7ed" stroke="#f97316"/>\n  <text x="433" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">3. الْخَرِيفُ (Sonbahar)</text>\n  <text x="368" y="102" font-size="11" fill="#334155">• الْجَوُّ غَائِمٌ (Bulutlu)</text>\n  <text x="368" y="128" font-size="11" fill="#334155">• الْجَوُّ عَاصِفٌ (Rüzgârlı)</text>\n  <text x="368" y="154" font-size="11" fill="#334155">• الْجَوُّ مُمْطِرٌ (Yağmurlu)</text>\n  <text x="433" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#9a3412">الْجَوُّ مُمْطِرٌ فِي الْخَرِيفِ</text>\n  <rect x="524" y="48" width="156" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="602" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">4. الشِّتَاءُ (Kış)</text>\n  <text x="536" y="102" font-size="11" fill="#334155">• الْجَوُّ بَارِدٌ (Soğuk)</text>\n  <text x="536" y="128" font-size="11" fill="#334155">• الْجَوُّ مُثْلِجٌ (Karlı)</text>\n  <text x="536" y="154" font-size="11" fill="#334155">• الثَّلْجُ أَبْيَضُ</text>\n  <text x="602" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">الشِّتَاءُ بَارِدٌ وَمُثْلِجٌ</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HAVA DURUMU SORULARI VE DUYGU İFADELERİ (كَيْفَ الْجَوُّ الْيَوْمَ؟)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hava ve Sıcaklık Sorma Kalıpları</text>\n  <text x="44" y="100" font-size="11.5" fill="#334155">• كَيْفَ الْجَوُّ الْيَوْمَ؟ (Bugün hava nasıl?)</text>\n  <text x="44" y="124" font-size="11.5" fill="#334155">• الْجَوُّ مُمْطِرٌ الْيَوْمَ. (Bugün hava yağmurlu.)</text>\n  <text x="44" y="148" font-size="11.5" fill="#334155">• كَمْ دَرَجَةُ الْحَرَارَةِ الْآنَ؟ (Sıcaklık kaç derece?)</text>\n  <text x="44" y="172" font-size="11.5" fill="#334155">• دَرَجَةُ الْحَرَارَةِ عَشْرُ دَرَجَاتٍ. (Sıcaklık 10 derece.)</text>\n  <text x="44" y="196" font-size="11.5" fill="#334155">• دَرَجَةُ الْحَرَارَةِ تَحْتَ الصِّفْرِ. (Sıfırın altında.)</text>\n  <text x="183" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">مَا أَجْمَلَ الْجَوَّ الْيَوْمَ! (Bugün hava ne güzel!)</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Hissiyat İfadeleri (أَشْعُرُ بِـ / أُحِسُّ بِـ)</text>\n  <text x="378" y="100" font-size="11.5" fill="#334155">• أَشْعُرُ بِالْبَرْدِ الشَّدِيدِ. (Şiddetli soğuk hissediyorum.)</text>\n  <text x="378" y="124" font-size="11.5" fill="#334155">• أُحِسُّ بِالْحَرِّ فِي الصَّيْفِ. (Yazın sıcaklık hissederim.)</text>\n  <text x="378" y="148" font-size="11.5" fill="#334155">• أَحْمِلُ الْمِظَلَّةَ فِي الْمَطَرِ. (Yağmurda şemsiye taşırım.)</text>\n  <text x="378" y="172" font-size="11.5" fill="#334155">• أَلْبَسُ الْمِعْطَفَ فِي الشِّتَاءِ. (Kışın palto giyerim.)</text>\n  <text x="378" y="196" font-size="11.5" fill="#334155">• أُحِبُّ فَصْلَ الرَّبِيعِ. (İlkbahar mevsimini severim.)</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">أَشْعُرُ بِالْبَرْدِ لِذٰلِكَ أَلْبَسُ الْمِعْطَفَ</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BAĞLAÇLAR (لٰكِنْ، لِأَنَّ، لِذٰلِكَ) VE KÂİNATTAKİ İLAHİ DENGE</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Sebep-Sonuç ve Karşıtlık Bağlaçları</text>\n  <text x="44" y="102" font-size="11.5" font-weight="bold" fill="#92400e">1. لٰكِنْ (Fakat / Ama):</text>\n  <text x="44" y="122" font-size="11" fill="#334155">الْجَوُّ مُشْمِسٌ لٰكِنْ بَارِدٌ (Hava güneşli fakat soğuk)</text>\n  <text x="44" y="148" font-size="11.5" font-weight="bold" fill="#92400e">2. لِأَنَّ (Çünkü — Sebep bildirir):</text>\n  <text x="44" y="168" font-size="11" fill="#334155">أَحْمِلُ الْمِظَلَّةَ لِأَنَّ الْجَوَّ مُمْطِرٌ (Çünkü hava yağmurlu)</text>\n  <text x="44" y="194" font-size="11.5" font-weight="bold" fill="#92400e">3. لِذٰلِكَ (Bu yüzden — Sonuç bildirir):</text>\n  <text x="44" y="214" font-size="11" fill="#334155">الْجَوُّ مُمْطِرٌ لِذٰلِكَ أَحْمِلُ الْمِظَلَّةَ (Bu yüzden şemsiye...)</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kâinattaki Denge Ayetleri</text>\n  <text x="378" y="102" font-size="11" font-weight="bold" fill="#166534">• Ra\'d Suresi 12. Ayet:</text>\n  <text x="378" y="122" font-size="10.5" fill="#334155">هُوَ الَّذِي يُرِيكُمُ الْبَرْقَ خَوْفًا وَطَمَعًا وَيُنْشِئُ السَّحَابَ الثِّقَالَ</text>\n  <text x="378" y="142" font-size="10.5" fill="#475569">(Şimşeği gösteren ve ağır bulutları meydana getiren O\'dur)</text>\n  <text x="378" y="170" font-size="11" font-weight="bold" fill="#166534">• Yûnus Suresi 5. Ayet:</text>\n  <text x="378" y="190" font-size="10.5" fill="#334155">هُوَ الَّذِي جَعَلَ الشَّمْسَ ضِيَاءً وَالْقَمَرَ نُورًا</text>\n  <text x="378" y="210" font-size="10.5" fill="#475569">(Güneşi bir ışık kaynağı, ayı da bir nur yapan O\'dur)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
